NuclearPowerPlant.query:
query ($id: ID) {
  NuclearPowerPlant(id: $id) {
    name
    owner
    commissioning_year
    url
    country {
      name
    }
    reactors {
      name
      type
    }
    capacity {
      quantity
      unit {
        symbol
        name
      }
    }
  }
}

NuclearPowerPlant.template:
{{name}} is a nuclear power plant{{#if country}} in {{country.name}}{{/if}}{{#if owner}} owned by {{owner}}{{/if}}{{#if commissioning_year}}, commissioned {{commissioning_year}}{{/if}}.
{{#if capacity}}Capacity: {{capacity.quantity}} {{capacity.unit.symbol}}.{{/if}}
{{#each reactors}}Reactor {{this.name}}{{#if this.type}} ({{this.type}}){{/if}}. {{/each}}
{{#if url}}More: {{url}}{{/if}}

Reactor.query:
query ($id: ID) {
  Reactor(id: $id) {
    name
    type
    coolant {
      name
    }
    moderator {
      name
    }
    capacity {
      quantity
      unit {
        symbol
      }
    }
  }
}

Element.query:
query ($id: ID) {
  Element(id: $id) {
    element_name
    element_symbol
    atomic_number
    isotopes {
      isotope_name
      mass {
        quantity
        unit {
          symbol
        }
      }
      abundance {
        quantity
        unit {
          symbol
        }
      }
    }
  }
}
